import {expect} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {resolve,join} from 'node:path';
import {invertCube} from './lut-ui.mjs';
import {imageDigest} from './text-ui.mjs';
export async function exerciseLutManagement(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,prefix='Managed-'+randomUUID().slice(0,8),names=['A','B','C'].map(n=>prefix+'-'+n+'.cube'),cubes=names.map((n,i)=>(i===1?'# Input: S-Log3\n':'')+invertCube(n)),panel=page.locator('.lut-panel'),image=page.locator('.edit-image img'),sourceName=await image.getAttribute('alt'),original=await imageDigest(image);
 await panel.locator(':scope>summary').click();await panel.getByRole('combobox',{name:t('样式分组','Style group'),exact:true}).selectOption('all');await panel.getByRole('searchbox').fill(prefix);
 await panel.locator('input[type=file]').first().setInputFiles(names.map((name,i)=>({name,mimeType:'application/octet-stream',buffer:Buffer.from(cubes[i])})));await expect(panel.locator('.lut-import-report')).toContainText(t('新增 3','Added 3'));
 const choice=i=>panel.getByRole('button',{name:t('应用 LUT ','Apply LUT ')+names[i],exact:true}),more=i=>panel.getByRole('button',{name:t('更多样式操作 ','More style actions ')+names[i],exact:true}),group=panel.getByRole('combobox',{name:t('样式分组','Style group'),exact:true});
 await choice(2).click();await expect(choice(2)).toHaveAttribute('aria-pressed','true');await expect.poll(()=>imageDigest(image)).not.toBe(original);const graded=await imageDigest(image);await choice(1).click();await expect(choice(1)).toHaveAttribute('aria-pressed','true');await panel.getByRole('button',{name:t('刷新样式','Refresh styles'),exact:true}).click();await expect(panel.locator('[data-lut-group=recent]')).toContainText('2');
 await choice(0).click({button:'right'});await page.getByRole('menuitem',{name:t('收藏此样式','Favorite this style'),exact:true}).click();await expect(panel.getByRole('button',{name:t('收藏 LUT ','Favorite LUT ')+names[0],exact:true})).toHaveAttribute('aria-pressed','true');await expect(panel.locator('.lut-list [data-lut]').first()).toContainText(names[0]);await expect(panel.locator('[data-lut-group=favorite]')).toContainText('1');
 await panel.getByRole('combobox',{name:t('缩略图列数','Thumbnail columns')}).selectOption('2');await choice(0).focus();await page.keyboard.press('ArrowDown');await expect(choice(1)).toBeFocused();await page.keyboard.press('ArrowRight');await expect(choice(2)).toBeFocused();await page.keyboard.press('Escape');await expect(choice(1)).toHaveAttribute('aria-pressed','true');
 await more(1).click();await page.keyboard.press('Escape');await expect(page.getByRole('menu')).toHaveCount(0);await expect(more(1)).toBeFocused();await more(1).press('Enter');await page.keyboard.press('End');await expect(page.getByRole('menuitem',{name:t('移出此样式','Remove this style'),exact:true})).toBeFocused();await page.keyboard.press('ArrowUp');await expect(page.getByRole('menuitemradio',{name:t('输入：普通照片','Input: normal photo'),exact:true})).toBeFocused();await page.keyboard.press('Enter');await expect(panel.getByRole('combobox',{name:t('LUT 输入类型 ','LUT input type ')+names[1],exact:true})).toHaveValue('normal');
 await more(1).click();const download=page.waitForEvent('download');await page.getByRole('menuitem',{name:t('取出 CUBE 文件','Save CUBE file'),exact:true}).click();expect(readFileSync(await(await download).path(),'utf8')).toBe(cubes[1]);await expect.poll(()=>imageDigest(image)).toBe(graded);
 const hide=panel.getByRole('button',{name:t('移出全部已复制样式','Remove all copied styles'),exact:true});page.once('dialog',d=>d.dismiss());await hide.click();await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(3);
 page.once('dialog',d=>d.accept());await hide.click();await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(0);expect(await imageDigest(image)).toBe(graded);
 const save=page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))});await save.click();await expect(save).toBeEnabled();await page.goto(new URL(page.url()).port==='4185'?'/#/tools/edit':'/tools/darkroom');await expect(page).not.toHaveURL(/[?&]photo=/);await expect(page.locator('.edit-records')).toBeVisible();await page.reload();await page.locator('.edit-records>div>button').filter({hasText:sourceName}).first().click();await expect.poll(()=>imageDigest(image)).toBe(graded);await panel.locator(':scope>summary').click();await panel.getByRole('searchbox').fill(prefix);await group.selectOption('hidden');await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(3);
 await more(0).click();await page.getByRole('menuitem',{name:t('恢复此样式','Restore this style'),exact:true}).click();await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(2);await panel.getByRole('button',{name:t('恢复全部已复制样式','Restore all copied styles'),exact:true}).click();await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(0);await group.selectOption('all');await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(3);await expect(panel.getByRole('button',{name:t('收藏 LUT ','Favorite LUT ')+names[0],exact:true})).toHaveAttribute('aria-pressed','true');await expect(panel.getByRole('combobox',{name:t('LUT 输入类型 ','LUT input type ')+names[1],exact:true})).toHaveValue('normal');expect(await imageDigest(image)).toBe(graded);
 await choice(1).scrollIntoViewIfNeeded();await expect(choice(1).locator('img')).toBeVisible();await page.screenshot({path:info.outputPath('lut-management.png'),fullPage:true});await more(1).click();const menu=page.getByRole('menu'),bounds=await menu.boundingBox();expect(bounds.x).toBeGreaterThanOrEqual(0);expect(bounds.y).toBeGreaterThanOrEqual(0);expect(bounds.x+bounds.width).toBeLessThanOrEqual(page.viewportSize().width);expect(bounds.y+bounds.height).toBeLessThanOrEqual(page.viewportSize().height);await page.screenshot({path:info.outputPath('lut-management-menu.png')});await page.keyboard.press('Escape');if(lang==='en')expect(await panel.innerText()).not.toMatch(/[\u3400-\u9fff]/);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
}
export async function exerciseLargeLutTree(page){
 const pack='TreePack-'+randomUUID().slice(0,8),root=resolve('.test-artifacts/afterframe-upgrade',pack),sources=[];
 for(let i=0;i<300;i++){const dir=join(root,'G'+String(i).padStart(3,'0'),'Deep'),file=join(dir,'TreeLook'+i+'.cube'),text=invertCube('TreeLook'+i);mkdirSync(dir,{recursive:true});writeFileSync(file,text);sources.push([file,text]);}
 const panel=page.locator('.lut-panel'),image=page.locator('.edit-image img'),before=await imageDigest(image);await panel.locator(':scope>summary').click();await panel.getByRole('searchbox').fill(pack);await panel.locator('input[type=file]').nth(1).setInputFiles(root);await expect(panel.locator('.lut-import-report')).toContainText('新增 300',{timeout:60000});await panel.getByRole('button',{name:'展开全部目录',exact:true}).click();
 const tree=panel.locator('.lut-copied-tree'),paths=new Set();
 for(;;){expect(await panel.locator('.lut-tree-node').count()).toBeLessThanOrEqual(261);for(const path of await tree.locator('[data-tree-path]').evaluateAll(nodes=>nodes.map(n=>n.dataset.treePath)))if(path.startsWith(pack))paths.add(path);const next=tree.getByRole('button',{name:'下一页目录',exact:true});if(await next.isDisabled())break;await next.click();}
 expect(paths.size).toBe(601);const leaf=tree.locator('[data-tree-path="'+pack+'/G299/Deep"]');await leaf.getByRole('button',{name:/查看/}).click();await expect(panel.locator('.lut-list [data-lut]')).toHaveCount(1);await expect(panel.locator('.lut-list [data-lut]')).toContainText('TreeLook299.cube');await panel.getByRole('button',{name:'收起全部目录',exact:true}).click();await expect(tree.locator('.lut-tree-node')).toHaveCount(1);expect(await imageDigest(image)).toBe(before);for(const [file,text] of sources)expect(readFileSync(file,'utf8')).toBe(text);
}
